init_entities:
    ; Initialize all active game entities (12 entities)
    
    ; Ensure sprite system is reset whenever entities are initialized
    call init_sprites
    
    ; CRITICAL: Clear entity screen IDs to prevent ghost entities on restart
    ; This ensures all entities start with screen ID 0, even if they were
    ; moved to different screens in a previous game session
    ld hl, entity_screen_id
    ld de, entity_screen_id+1
    ld bc, 31                  ; Clear 32 entities (32-1 for LDIR)
    ld (hl), 0                 ; Set first byte to 0
    ldir                       ; Copy to rest of array
    
    ; Initialize State Machine variables (Clear to 0)
    ld hl, entity_sm_ptr_l
    ld de, entity_sm_ptr_l+1
    ld bc, 31
    ld (hl), 0
    ldir

    ld hl, entity_sm_ptr_h
    ld de, entity_sm_ptr_h+1
    ld bc, 31
    ld (hl), 0
    ldir

    ld hl, entity_sm_timer_l
    ld de, entity_sm_timer_l+1
    ld bc, 31
    ld (hl), 0
    ldir

    ld hl, entity_sm_timer_h
    ld de, entity_sm_timer_h+1
    ld bc, 31
    ld (hl), 0
    ldir
    
    call init_player_1
    call init_nucleo_1
    call init_nucleo_2
    call init_nucleo_3
    call init_nucleo_4
    call init_nucleo_5
    call init_nucleo_6
    call init_nucleo_7
    call init_nucleo_8
    call init_nucleo_9
    call init_nucleo_10
    call init_coin_1
    ret

update_entities:
    ; Update all active entities (12 entities)
    call update_player_1
    call update_nucleo_1
    call update_nucleo_2
    call update_nucleo_3
    call update_nucleo_4
    call update_nucleo_5
    call update_nucleo_6
    call update_nucleo_7
    call update_nucleo_8
    call update_nucleo_9
    call update_nucleo_10
    call update_coin_1
    ret

init_player_1:
    ; Initialize Player 1 at real position from JSON
    ; JSON position: (15, 19) tiles = (120, 152) pixels
    ; Template: tpl_player
    ; Components: Position, Sprite, Collision, Input, Behavior, Health, Animation
    ; Direction mask: #0F (1111b) = All directions

    ; Set entity ID and component mask (DYNAMIC - based on template)
    ld a, 0             ; Entity ID
    ld b, #3FB              ; Component mask (1111111011b)
    call create_entity         ; Create with actual components from template

    ; Set real position from JSON data
    ld hl, entity_x_pos
    ld e, 0             ; Entity index
    ld d, 0
    add hl, de
    ld (hl), 120         ; Set real X position from JSON

    ld hl, entity_y_pos
    add hl, de
    ld (hl), 152         ; Set real Y position from JSON

    ; Set entity screen ID (for multi-screen support)
    ld hl, entity_screen_id
    add hl, de
    ld (hl), 0                 ; Screen ID (calculated from project data)

    ; Set sprite pattern and color (renderable entity)
    ld hl, sprite_pattern
    add hl, de
    ld (hl), 0          ; Use entity index * 4 for 16x16 sprites

    ld hl, sprite_color
    add hl, de
    ld (hl), 2                ; Distinct color for debugging


    ; Set direction mask for Cursors component (if entity has Input component)
    ld hl, entity_dir_mask
    add hl, de
    ld (hl), #0F            ; Direction restrictions: All directions

    ; Make sprite visible immediately (only if on screen 0 or current screen)
    ; For safety, we'll let the update loop handle visibility based on screen ID
    ; but we can initialize it here if it's on screen 0
    ld a, 0
    or a                       ; Check if screen 0
    jr nz, .skip_show_0 ; Skip if not screen 0

    ; Force update sprite attributes (using correct multi-layer config)
    ld c, 0             ; Entity Index
    call force_update_entity_sprite

.skip_show_0:

    ret

update_player_1:
    ; Update Player 1 logic with real behavior
    ; Check if entity has input component (player entities)
    ld a, 0
    ld hl, entity_comp_masks
